#include <Arduino.h>

// ============================================================================
// WYMUSZENIE KONFIGURACJI DLA LILYGO T-EMBED (ST7789 SPI) W KOMPILATORZE ONLINE
// ============================================================================
#define USER_SETUP_LOADED 1      // Informujemy bibliotekę, że sami podajemy konfigurację

#define ST7789_DRIVER     1      // Typ sterownika ekranu
#define TFT_WIDTH         170    // Rozdzielczość fizyczna (krótszy bok)
#define TFT_HEIGHT        320    // Rozdzielczość fizyczna (dłuższy bok)

// Piny SPI dla LilyGo T-Embed (ESP32-S3)
#define TFT_MOSI          9
#define TFT_SCLK          10
#define TFT_CS            41
#define TFT_DC            16
#define TFT_RST           -1     // Brak fizycznego pinu resetu ekranu

// Kolory i czcionki
#define LOAD_GLCD         1      // Ładowanie podstawowej czcionki systemowej
#define SPI_FREQUENCY     27000000 // Częstotliwość taktowania SPI dla ST7789

// Dopiero TERAZ załączamy bibliotekę graficzną
#include <TFT_eSPI.h>

// Definicja pinów zasilania i podświetlenia dla T-Embed
#define PIN_POWER_ON      15 
#define PIN_LCD_BL        21 

TFT_eSPI tft = TFT_eSPI();

void setup() {
    Serial.begin(115200);
    delay(500);

    Serial.println();
    Serial.println("--- LILYGO T-EMBED ---");
    Serial.println("WEB COMPILER TEST V4");

    // Włączenie zasilania peryferiów (CC1101, LCD itp.)
    pinMode(PIN_POWER_ON, OUTPUT);
    digitalWrite(PIN_POWER_ON, HIGH);
    delay(200);

    // Inicjalizacja ekranu przed włączeniem podświetlenia
    Serial.println("Initializing TFT...");
    tft.init();

    // Rotacja pozioma dopasowana do obudowy T-Embed
    tft.setRotation(3); 
    tft.fillScreen(TFT_BLACK); 

    // Włączenie podświetlenia ekranu
    pinMode(PIN_LCD_BL, OUTPUT);
    digitalWrite(PIN_LCD_BL, HIGH);
    delay(100);

    // Dynamiczny test kolorów
    Serial.println("Running color test...");
    tft.fillScreen(TFT_RED);    delay(500);
    tft.fillScreen(TFT_GREEN);  delay(500);
    tft.fillScreen(TFT_BLUE);   delay(500);

    // Ekran końcowy z wyśrodkowanym tekstem
    tft.fillScreen(TFT_BLACK);
    tft.drawRect(0, 0, tft.width(), tft.height(), TFT_CYAN);

    tft.setTextColor(TFT_WHITE, TFT_BLACK);

    // Napis LILYGO
    tft.setTextSize(3);
    tft.setCursor((tft.width() - tft.textWidth("LILYGO")) / 2, 35);
    tft.println("LILYGO");

    // Napis DISPLAY OK
    tft.setTextSize(2);
    tft.setTextColor(TFT_GREEN, TFT_BLACK);
    tft.setCursor((tft.width() - tft.textWidth("DISPLAY OK")) / 2, 80);
    tft.println("DISPLAY OK");

    // Napis ST7789
    tft.setTextSize(1);
    tft.setTextColor(TFT_LIGHTGRAY, TFT_BLACK);
    tft.setCursor((tft.width() - tft.textWidth("ST7789 (320x170)")) / 2, 130);
    tft.println("ST7789 (320x170)");

    Serial.println("DISPLAY TEST FINISHED");
}

void loop() {
    delay(1000);
}
